class WeightOptimizer:
    """Dynamically adjusts grading weights based on historical success rates."""
    @staticmethod
    def get_optimized_weights(issue_rule: str) -> np.ndarray:
        weights = DEFAULT_WEIGHTS.copy()
        try:
            from mongo import get_historical_stats
            stats = get_historical_stats()
            rule_stats = next((s for s in stats if s["_id"] == issue_rule), None)
            if rule_stats:
                # If this rule historically takes many iterations,
                # trust the Confidence row less
                if rule_stats["avg_iterations"] > 2:
                    weights[2] *= 0.8
                if rule_stats["avg_confidence"] > 0.8 and rule_stats["avg_iterations"] > 3:
                    weights[2] *= 0.5
            optimized = weights / weights.sum()
            return optimized.tolist()
        except Exception:
            return DEFAULT_WEIGHTS.tolist()

def evaluate(raw_cells, issue_rule="unknown", iteration=1, weights=None):
    scores = np.clip(np.array(raw_cells, dtype=float), 0.0, 1.0)
    w_arr = np.array(weights) if weights is not None \
        else np.array(WeightOptimizer.get_optimized_weights(issue_rule))
    # Late-iteration penalty: repeated failures reduce trust in Confidence row
    if iteration > 1:
        w_arr[2] *= 1.0 + (0.5 * min(iteration - 1, 4))
        w_arr /= w_arr.sum()
    overall = float(np.sum(scores * w_arr))
    letter, desc = assign_grade(overall)
    return GradeResult(overall_score=round(overall, 4), letter_grade=letter, grade_desc=desc, ...)

class AttackFingerprintClassifier(nn.Module):
    def __init__(self, input_size=15, num_classes=7):
        super().__init__()
        self.fc1 = nn.Linear(input_size, 128)
        self.fc2 = nn.Linear(128, 64)
        self.fc3 = nn.Linear(64, 32)
        self.fc4 = nn.Linear(32, num_classes)
        self.relu = nn.ReLU()
        self.dropout = nn.Dropout(0.3)

    def forward(self, x):
        x = self.dropout(self.relu(self.fc1(x)))
        x = self.dropout(self.relu(self.fc2(x)))
        x = self.relu(self.fc3(x))
        return self.fc4(x)

class AttackPredictionLSTM(nn.Module):
    def __init__(self, input_size=10, hidden_size=64, num_layers=2):
        super().__init__()
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers,
                             batch_first=True, dropout=0.3)
        self.fc1 = nn.Linear(hidden_size, 32)
        self.fc2 = nn.Linear(32, 1)

    def forward(self, x):
        lstm_out, _ = self.lstm(x)
        last_output = lstm_out[:, -1, :]
        x = self.relu(self.fc1(last_output))
        return self.fc2(x)

