def start(self):
    start_time = time.time()
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = [executor.submit(self.run_attack, i) for i in range(10)]
        try:
            while time.time() - start_time < self.duration:
                time.sleep(1)
        finally:
            self.stop_event.set()
            for future in futures:
                future.cancel()

@app.post("/auth/login")
def login(req: LoginRequest):
    role = USERS.get(req.mobile_number)  # prototype mock store
    if not role:
        raise HTTPException(status_code=401, detail="User not registered")
    payload = {
        "mobile": req.mobile_number,
        "role": role,
        "exp": datetime.datetime.utcnow() + datetime.timedelta(hours=6)
    }
    token = jwt.encode(payload, SECRET, algorithm=ALGORITHM)
    return {"message": "Login successful", "token": token, "role": role}

@app.post("/auth/verify")
def verify(token: str):
    try:
        decoded = jwt.decode(token, SECRET, algorithms=[ALGORITHM])
        return {"valid": True, "mobile": decoded["mobile"], "role": decoded["role"]}
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
